def check_order(core, order_links, scopes):
    """Validate the elimination order and the promised width."""
    if len(order_links) != len(core):
        raise Invalid('order length')
    seen = set()
    for link in order_links:
        if link in seen:
            raise Invalid('duplicate order entry')
        seen.add(link)
    if seen != set(core):
        raise Invalid('order is not a permutation of the core links')
    index = {link: position for position, link in enumerate(core)}
    adjacency = {position: set() for position in range(len(core))}
    for scope in scopes.values():
        for a in scope:
            for b in scope:
                if a != b:
                    adjacency[a].add(b)
    for link in order_links:
        node = index[link]
        neighbours = adjacency[node]
        if len(neighbours) > MAX_WIDTH:
            raise Invalid('width promise violated')
        group = list(neighbours)
        for a in group:
            for b in group:
                if a != b:
                    adjacency[a].add(b)
                    adjacency[b].add(a)
        del adjacency[node]
    return [index[link] for link in order_links]


